//! Report account balances from a ledger file.

use std::collections::HashMap;
use std::env;
use std::fs;

/// Parse a decimal amount such as `12.05` into cents, exactly.
fn to_cents(amount: &str) -> Option<i128> {
    let (whole, frac) = match amount.split_once('.') {
        Some((w, f)) => (w, f),
        None => (amount, ""),
    };
    if whole.is_empty() && frac.is_empty() {
        return None;
    }
    if !whole.bytes().chain(frac.bytes()).all(|b| b.is_ascii_digit()) {
        return None;
    }
    let whole: i128 = if whole.is_empty() { 0 } else { whole.parse().ok()? };
    let mut frac_cents: i128 = 0;
    for (i, b) in frac.bytes().take(2).enumerate() {
        frac_cents += i128::from(b - b'0') * if i == 0 { 10 } else { 1 };
    }
    whole.checked_mul(100)?.checked_add(frac_cents)
}

fn format_cents(cents: i128) -> String {
    let sign = if cents < 0 { "-" } else { "" };
    let cents = cents.abs();
    format!("{}{}.{:02}", sign, cents / 100, cents % 100)
}

fn main() {
    let path = env::args().nth(1).expect("a ledger path");
    let bytes = fs::read(&path).expect("a readable ledger");
    let text = String::from_utf8_lossy(&bytes);
    let mut lines = text.lines().map(|l| l.trim_end_matches('\r'));
    let n: usize = lines
        .next()
        .and_then(|h| h.split_whitespace().nth(1))
        .and_then(|s| s.parse().ok())
        .unwrap_or(0);

    let mut balances: HashMap<String, i128> = HashMap::new();
    for (index, line) in lines.take(n).enumerate() {
        let mut fields = line.rsplitn(3, char::is_whitespace);
        let amount = fields.next().unwrap_or("");
        let kind = fields.next().unwrap_or("");
        let account = fields.next().unwrap_or("").trim_end();
        let cents = to_cents(amount).unwrap_or(0);
        let signed = match kind {
            "debit" => -cents,
            "credit" => cents,
            _ => {
                println!("ERROR line {}", index + 1);
                return;
            }
        };
        *balances.entry(account.to_string()).or_insert(0) += signed;
    }

    let mut entries: Vec<(String, i128)> = balances.into_iter().collect();
    entries.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.as_bytes().cmp(b.0.as_bytes())));
    let mut total = 0;
    for (account, balance) in &entries {
        println!("{} {}", account, format_cents(*balance));
        total += balance;
    }
    println!("TOTAL {}", format_cents(total));
}
